sys_script_client.script:
function onLoad() {
    runBulkProcessClientScript(); // Start only once

}

var isProcessing = false;
var pollingStopped = false;

function runBulkProcessClientScript() {
    if (pollingStopped) return; // Prevent overlapping calls and stop after termination
    var bulkState = g_form.getValue('state');
    if (bulkState == '1' || bulkState == '2') {
        var gaType = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkProcessUtils');
        gaType.addParam('sysparm_name', 'getBulkTaskType');
        gaType.addParam('sysparm_sys_id', g_form.getUniqueValue());
        gaType.getXMLAnswer(function(bulkTaskType) {
            var gaStatus = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkProcessUtils');
            gaStatus.addParam('sysparm_name', 'getProcessingStatus');
            gaStatus.addParam('sysparm_sys_id', g_form.getUniqueValue());
            gaStatus.getXMLAnswer(function(processingStatus) {
                // if (
                //     (bulkTaskType == "Maker" && (processingStatus.indexOf('Maker Tasks linking completed') != -1) || processingStatus.indexOf('Maker Tasks linked for') != -1) ||
                //     (bulkTaskType == "Checker" && processingStatus.indexOf('Checker Tasks linking completed') != -1) ||
                //     (bulkTaskType == "GHSS Handler" && processingStatus.indexOf('Handler Tasks linking completed') != -1)
                // ) {
                //     g_form.clearMessages();
                //     g_form.addInfoMessage(processingStatus);
                //     isProcessing = false;
                //     pollingStopped = true; // Stop further polling
                //     return;
                // }

                var gaProcess = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkProcessUtils');
                gaProcess.addParam('sysparm_name', 'bulkProcess');
                gaProcess.addParam('sysparm_sys_id', g_form.getUniqueValue());
                gaProcess.getXMLAnswer(function() {});
                pollProcessingStatus(bulkTaskType);
            });
        });
    }
}

function pollProcessingStatus(bulkTaskType) {
    var lastMessage = '';
    var interval = setInterval(function() {
        if (pollingStopped) {
            clearInterval(interval);
        }
        var gaStatus = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkProcessUtils');
        gaStatus.addParam('sysparm_name', 'getProcessingStatus');
        gaStatus.addParam('sysparm_sys_id', g_form.getUniqueValue());
        gaStatus.addParam('sysparm_rand', Math.random());
        gaStatus.getXMLAnswer(function(response) {
            var isTerminated =
                response &&
                (
                    response.indexOf('Maker Tasks linking completed') != -1 ||
                    response.indexOf('Checker Tasks linking completed') != -1 ||
                    response.indexOf('Handler Tasks linking completed') != -1
                );

            // Only update the message if it has changed
            if (response && response !== lastMessage) {
                g_form.clearMessages();
                g_form.addInfoMessage(response);
                lastMessage = response;
            }

            if (isTerminated) {
                clearInterval(interval);
                pollingStopped = true;
            }
        });
    }, 3000);
}
